/*
 * A205706  The number j such that 8 divides prime(k)-prime(j), where
 *          k(n)=A205705(n).
 * https://oeis.org/A205706
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = j, where for k = A205705(n), prime(k) == prime(j) (mod
 *            8), j<k; for each k the j's ascend (generated by a sieve-like
 *            prime search)
 * Range:     u8 n <= 70, u16 n <= 70, u32 n <= 70, u64 n <= 70, u128 n <= 70,
 *            big any n
 * Validated: partial, pass, 70 terms through n = 70 (2026-11-07)
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stddef.h>
#include <stdint.h>
#include <stdlib.h>

static uint32_t *A205706_cache = NULL;
static size_t A205706_len = 0, A205706_cap = 0;
static uint32_t *A205706_pr = NULL;
static size_t A205706_pn = 0, A205706_pcap = 0;
static uint32_t A205706_next = 2;

static void A205706_push(uint32_t v)
{
    if (A205706_len == A205706_cap) {
        A205706_cap = A205706_cap ? A205706_cap * 2 : 1024;
        A205706_cache = (uint32_t *)realloc(A205706_cache, A205706_cap * sizeof(uint32_t));
        if (!A205706_cache) abort();
    }
    A205706_cache[A205706_len++] = v;
}

static void A205706_step(void)
{
    uint32_t x = A205706_next;
    for (;; ++x) {
        int ok = (x >= 2);
        for (size_t i = 0; ok && i < A205706_pn; ++i) {
            uint32_t p = A205706_pr[i];
            if ((uint64_t)p * p > x) break;
            if (x % p == 0) ok = 0;
        }
        if (ok) break;
    }
    if (A205706_pn == A205706_pcap) {
        A205706_pcap = A205706_pcap ? A205706_pcap * 2 : 1024;
        A205706_pr = (uint32_t *)realloc(A205706_pr, A205706_pcap * sizeof(uint32_t));
        if (!A205706_pr) abort();
    }
    A205706_pr[A205706_pn++] = x;
    A205706_next = x + 1;
    for (size_t j = 0; j + 1 < A205706_pn; ++j)
        if (((A205706_pr[j] ^ x) & 7U) == 0 && ((A205706_pr[j] - x) & 7U) == 0)
            A205706_push((uint32_t)(j + 1));
}

seq_t a(idx_t n)
{
    while (A205706_len < (size_t)n) A205706_step();
    return (seq_t)A205706_cache[(size_t)n - 1];
}
